import{_ as i,o as l,c as e,a2 as t}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"AI 基础概念","description":"","frontmatter":{},"headers":[],"relativePath":"ai/basics.md","filePath":"ai/basics.md","lastUpdated":1786350421000}'),r={name:"ai/basics.md"};function o(n,a,d,p,s,h){return l(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="ai-基础概念" tabindex="-1">AI 基础概念 <a class="header-anchor" href="#ai-基础概念" aria-label="Permalink to &quot;AI 基础概念&quot;">​</a></h1><p>一句话：AI 是让机器从数据中学习规律并完成任务的一类方法，不等于“会思考的人”。</p><h2 id="ai、机器学习和模型" tabindex="-1">AI、机器学习和模型 <a class="header-anchor" href="#ai、机器学习和模型" aria-label="Permalink to &quot;AI、机器学习和模型&quot;">​</a></h2><p>常见说法可以这样区分：</p><ul><li>AI：更大的概念，指让机器表现出某种智能能力。</li><li>机器学习：AI 的一类方法，让系统从数据中学习规律。</li><li>深度学习：机器学习的一类方法，使用多层神经网络学习复杂表示。</li><li>模型：学习后的参数和结构组合，用来做预测、生成、分类或决策。</li></ul><p>当我们说“调用一个 AI 模型”时，通常是在给模型输入数据，让它根据训练中学到的规律输出结果。</p><h2 id="训练和推理" tabindex="-1">训练和推理 <a class="header-anchor" href="#训练和推理" aria-label="Permalink to &quot;训练和推理&quot;">​</a></h2><p>训练是让模型学习的阶段。</p><p>训练时需要：</p><ul><li>数据：文本、图片、音频、代码、标注结果等。</li><li>目标：希望模型学会什么，例如预测下一个词、识别图片类别、生成图片。</li><li>参数：模型内部可调整的数字。</li><li>损失函数：衡量模型输出和目标之间差距的方法。</li></ul><p>推理是使用模型的阶段。用户输入 Prompt、图片或其他上下文，模型根据已有参数生成结果。大多数普通用户接触到的是推理，而不是训练。</p><h2 id="token-和上下文" tabindex="-1">Token 和上下文 <a class="header-anchor" href="#token-和上下文" aria-label="Permalink to &quot;Token 和上下文&quot;">​</a></h2><p>Token 是模型处理文本的基本单位。它不一定等于一个字或一个词，中文、英文、标点、空格都可能被拆成不同 token。</p><p>上下文窗口是模型一次能看到的 token 范围。它会影响：</p><ul><li>能塞进去多少历史对话。</li><li>能否阅读长文档。</li><li>是否容易忘记前面信息。</li><li>输出成本和速度。</li></ul><p>上下文越长不代表效果一定越好。无关信息太多时，模型反而更难抓住重点。</p><h2 id="embedding" tabindex="-1">Embedding <a class="header-anchor" href="#embedding" aria-label="Permalink to &quot;Embedding&quot;">​</a></h2><p>Embedding 是把文本、图片或其他对象转换成向量表示的方法。</p><p>直观理解：意思相近的内容，在向量空间里距离更近。它常用于：</p><ul><li>搜索相似文档。</li><li>推荐相关内容。</li><li>RAG 中检索知识片段。</li><li>聚类和去重。</li></ul><p>Embedding 本身不直接回答问题，它更像“可计算的语义索引”。</p><h2 id="参数、能力和限制" tabindex="-1">参数、能力和限制 <a class="header-anchor" href="#参数、能力和限制" aria-label="Permalink to &quot;参数、能力和限制&quot;">​</a></h2><p>模型参数可以理解为模型内部保存知识和规律的数字。参数更多通常代表表达能力更强，但也带来更高的训练和推理成本。</p><p>评价模型时不要只看参数量，还要看：</p><ul><li>训练数据质量。</li><li>架构和训练方法。</li><li>推理速度和成本。</li><li>上下文长度。</li><li>工具调用、结构化输出、多模态能力。</li><li>是否适合你的任务。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>“AI 什么都懂”：模型会生成看似合理的内容，但可能事实错误。</li><li>“模型越大越好”：任务简单时，小模型可能更快更便宜。</li><li>“把资料全塞进去最好”：上下文需要筛选和组织。</li><li>“联网就一定准确”：联网只是增加信息来源，不等于自动判断真假。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>继续阅读 <a href="/llm/basics">大模型入门</a>，了解语言模型如何生成内容，以及为什么需要 Prompt、检索和验证。</p>',29)])])}const b=i(r,[["render",o]]);export{u as __pageData,b as default};
